<script setup>
import { onMounted, ref } from 'vue'
import { api } from '../api'
const emit=defineEmits(['error'])
const items=ref([]),form=ref({category:'AI应用开发',title:'',body:'',source_url:null}),editing=ref(''),query=ref(''),results=ref(null),url=ref(''),busy=ref(false),message=ref('')
async function load(){items.value=await api('/knowledge?limit=100')}
async function action(fn){busy.value=true;message.value='';try{await fn()}catch(e){emit('error',e.message)}finally{busy.value=false}}
async function save(){await action(async()=>{await api(editing.value?`/knowledge/${editing.value}`:'/knowledge',{method:editing.value?'PUT':'POST',body:{...form.value,source_url:form.value.source_url||null}});editing.value='';form.value={category:form.value.category,title:'',body:'',source_url:null};await load();message.value='素材已保存，之后创建的任务会检索它'})}
async function index(id){await action(async()=>{const r=await api(`/knowledge/${id}/index`,{method:'POST'});message.value=`已生成 ${r.chunks} 个分块，检索方式：${r.mode==='vector'?'向量':'关键词'}`})}
async function remove(id){await action(async()=>{await api(`/knowledge/${id}`,{method:'DELETE'});await load();message.value='素材已删除，历史任务保留原快照'})}
function edit(item){editing.value=item.id;form.value={category:item.category,title:item.title,body:item.body,source_url:item.source_url||null}}
async function search(){await action(async()=>{results.value=await api(`/knowledge/search?category=${encodeURIComponent(form.value.category)}&query=${encodeURIComponent(query.value)}`)})}
async function importUrl(){await action(async()=>{await api('/knowledge/import-url',{method:'POST',body:{url:url.value,category:form.value.category}});await load();message.value='网页已导入，请核对清洗后的正文与来源';url.value=''})}
onMounted(()=>action(load))
</script>
<template><div class="intro compact"><h2>让内容有可核对的资料。</h2><p>保留来源、编辑正文、分块检索。配置 Embedding 后可用语义检索；未配置时显示实际的关键词检索结果。</p></div><section class="panel"><h3>检验资料能否被找到</h3><div class="search-row"><input v-model="query" maxlength="2000" placeholder="输入一个具体问题"><button :disabled="busy||!query" @click="search">检索</button></div><template v-if="results"><p class="muted">检索方式：{{results.mode}} · {{results.items.length}} 条</p><article v-for="r in results.items" :key="r.id" class="caption-box"><strong>{{r.title}}</strong><p class="preserve">{{r.body}}</p><small>引用 ID：{{r.id}} · 相关度 {{r.score}}</small></article></template><details><summary>从公开网页导入资料</summary><p class="muted">仅导入可直接读取、你有权使用的公开正文；无法读取时可粘贴资料。</p><div class="search-row"><input v-model="url" type="url" placeholder="https://…"><button :disabled="busy||!url" @click="importUrl">读取并导入</button></div></details></section><div class="library-grid"><form class="panel" @submit.prevent="save"><h3>{{editing?'修改素材':'添加课程素材'}}</h3><label>课程方向<select v-model="form.category"><option>AI应用开发</option><option>AI训练师</option></select></label><label>标题<input v-model="form.title" required maxlength="200"></label><label>来源地址（可选）<input v-model="form.source_url" type="url" maxlength="1000"></label><label>已核实的正文<textarea v-model="form.body" rows="12" required maxlength="12000"></textarea></label><button class="primary" :disabled="busy">保存素材</button><button v-if="editing" type="button" @click="editing=''">取消修改</button><p v-if="message" class="muted" role="status">{{message}}</p></form><div class="library-list"><article v-for="item in items" :key="item.id" class="panel"><span class="pill">{{item.category}}</span><h3>{{item.title}}</h3><p class="preserve">{{item.body}}</p><a v-if="item.source_url" :href="item.source_url" target="_blank" rel="noopener noreferrer">查看来源 ↗</a><div class="actions wrap"><button :disabled="busy" @click="edit(item)">编辑</button><button :disabled="busy" @click="index(item.id)">建立 / 更新索引</button><button :disabled="busy" @click="remove(item.id)">删除素材</button></div></article><p v-if="!items.length" class="panel muted">先加入真实课程说明、案例或验证过的操作步骤。</p></div></div></template>
